insert into content.content_block (place_id,section,slot,ord,body,fact_refs,status,author,field)
select 'area:grand-massif',v.section,v.slot,v.ord,v.body,v.refs::text[],'review','loader',v.field from (values
('method','line',1,'Flaine, Les Carroz, Morillon, Samoëns and Sixt-Fer-à-Cheval, the five resorts on the Grand Massif pass, each treated as one area with its upper stations: Samoëns 1600 and Vercland with Samoëns, Morillon 1100 with Morillon, and Flaine Forêt, Montsoleil and Le Hameau with Flaine. Sharing the pass is recorded separately from being linked by lift and piste.','{}','method.items.0.dd'),
('method','line',2,'How links were found','{}','method.items.1.dt'),
('method','line',3,'A resort counts as linked when a route of lifts and pistes reaches it in the OpenStreetMap data. Drags run one way and gondolas and cable cars may be ridden down. Every count starts at the village lifts. The two Sixt chairs that no longer run are left out, and the free skibus from Sixt and Vercland to the Grand Massif Express counts as a link with no lift ride.','{}','method.items.1.dd'),
('method','line',4,'Piste totals','{}','method.items.2.dt'),
('method','line',5,'Operator and measured figures are both shown and never averaged. Piste length from OpenStreetMap is used only to compare resorts and grades.','{}','method.items.2.dd'),
('method','line',6,'Comparisons','{}','method.items.3.dt'),
('method','line',7,'The four areas compared use the same source for each row, so a figure can be set against its neighbour.','{}','method.items.3.dd'),
